# puter's icons: each freedesktop icon name apps ask for, its context, and
# the Carbon icon (IBM's, theme/carbon, Apache 2.0) drawn for it. theme/make
# builds the icon theme from this: every icon in ink, at 16px from Carbon's
# own 16px drawing where it has one and from its 32px one halved otherwise
# (Carbon draws on even pixels, so halved its 2px lines are sharp 1px ones);
# 24 and 64 from the 32. Names not here fall back to Breeze.
#
# name                        context     carbon

# Files and places.
folder                        places      folder
folder-open                   places      folder--open
inode-directory               places      folder
user-home                     places      home
user-desktop                  places      screen
user-trash                    places      trash-can
user-trash-full               places      trash-can
folder-documents              places      document
folder-download               places      download
folder-downloads              places      download
folder-music                  places      music
folder-pictures               places      image
folder-videos                 places      video
folder-remote                 places      folder--shared
network-workgroup             places      network--3
network-server                places      bare-metal-server
computer                      devices     laptop
drive-harddisk                devices     data--base
drive-harddisk-system         devices     data--base
drive-removable-media         devices     usb
drive-optical                 devices     radio-button
media-optical                 devices     radio-button
text-x-generic                mimetypes   document
text-plain                    mimetypes   document
unknown                       mimetypes   document--blank
application-octet-stream      mimetypes   document--blank
image-x-generic               mimetypes   image
video-x-generic               mimetypes   video
audio-x-generic               mimetypes   music
application-pdf               mimetypes   document--pdf
package-x-generic             mimetypes   zip
application-zip               mimetypes   zip
application-x-archive         mimetypes   zip
text-html                     mimetypes   html
text-x-script                 mimetypes   script
application-x-executable      mimetypes   terminal
application-x-shellscript     mimetypes   script
x-office-document             mimetypes   document
x-office-presentation         mimetypes   presentation-file
text-x-csrc                   mimetypes   code
text-x-python                 mimetypes   code
text-x-makefile               mimetypes   code

